function getUiStrings(languageCode = "IT") {
  const baseStrings = uiStrings[languageCode] || uiStrings.IT;
  const onboardingStrings = onboardingUiStrings[languageCode] || onboardingUiStrings.EN;
  return { ...baseStrings, ...onboardingStrings };
}

function getStopTitle(tappa, languageCode = currentLanguage) {
  const titles = stopTitles[tappa.numero];
  if (!titles) {
    return tappa.titolo;
  }

  return titles.IT || tappa.titolo;
}

function getUrlState() {
  const params = new URLSearchParams(window.location.search);
  const rawStop = params.get("tappa") || params.get("stop");
  const stopNumber = Number.parseInt(rawStop || "", 10);
  const storedStop = Number.parseInt(getStoredValue(LAST_STOP_STORAGE_KEY), 10);
  const linkedStop = tappe.find((tappa) => tappa.numero === stopNumber) ||
    tappe.find((tappa) => tappa.numero === storedStop) || null;
  const rawLanguage = params.get("lang") || params.get("lingua");
  const linkedLanguage = rawLanguage ? rawLanguage.trim().toUpperCase() : null;

  return {
    stop: linkedStop,
    language: siteLanguages.includes(linkedLanguage) ? linkedLanguage : null,
  };
}

function normalizeLanguageCode(value) {
  if (!value) {
    return null;
  }

  const normalized = String(value).trim().slice(0, 2).toUpperCase();
  return siteLanguages.includes(normalized) ? normalized : null;
}

function getStoredValue(key) {
  try {
    return window.localStorage?.getItem(key) || "";
  } catch (error) {
    return "";
  }
}

function setStoredValue(key, value) {
  try {
    window.localStorage?.setItem(key, value);
  } catch (error) {
    // Local storage can be unavailable in private browsing or strict contexts.
  }
}

function getBrowserLanguage() {
  const browserLanguages = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const language of browserLanguages) {
    const normalized = normalizeLanguageCode(language);
    if (normalized) {
      return normalized;
    }
  }

  return "EN";
}

function getInitialLanguage(urlLanguage) {
  return (
    normalizeLanguageCode(urlLanguage) ||
    normalizeLanguageCode(getStoredValue(LANGUAGE_STORAGE_KEY)) ||
    getBrowserLanguage() ||
    "EN"
  );
}

function syncSelectedLanguagesForCurrentLanguage() {
  tappe.forEach((tappa) => {
    const option = getAudioOptions(tappa).find((audioOption) => audioOption.codice === currentLanguage);
    if (option) {
      selectedLanguageByStop.set(tappa.numero, currentLanguage);
    }
  });
}

function syncUrlState({ replace = false } = {}) {
  if (!window.history || !activeStopNumber) {
    return;
  }

  const params = new URLSearchParams(window.location.search);
  params.set("tappa", String(activeStopNumber));
  params.set("lang", currentLanguage.toLowerCase());

  const nextUrl = `${window.location.pathname}?${params.toString()}`;
  const currentUrl = `${window.location.pathname}${window.location.search}`;

  if (nextUrl === currentUrl) {
    return;
  }

  const method = replace ? "replaceState" : "pushState";
  window.history[method]({ tappa: activeStopNumber, lang: currentLanguage }, "", nextUrl);
}

function setCurrentLanguage(languageCode, options = {}) {
  currentLanguage = normalizeLanguageCode(languageCode) || "EN";
  syncSelectedLanguagesForCurrentLanguage();
  closeGlobalLanguageMenu();

  if (options.persist !== false) {
    setStoredValue(LANGUAGE_STORAGE_KEY, currentLanguage);
  }

  renderStaticTexts();
  renderGlobalLanguageSelector();
  renderOnboardingTexts();
  renderOnboardingLanguageSelector();
  renderStopsList();

  // Keep an already open help guide aligned with the newly selected UI language.
  if (guideLayer && !guideLayer.classList.contains("is-hidden")) {
    renderGuideStep();
  }

  if (activeStopNumber !== null) {
    const activeStop = tappe.find((tappa) => tappa.numero === activeStopNumber);
    if (activeStop) {
      focusStop(activeStop, {
        skipFly: true,
        preservePlayback: true,
        replaceUrl: true,
        syncUrl: options.syncUrl,
      });
    }
  } else if (options.syncUrl !== false) {
    syncUrlState({ replace: true });
  }

  pulseActiveLanguageChips();
  if (options.animate !== false) {
    animateTranslatedContent();
  }
}

function replayAnimationClass(element, className, duration = 420) {
  if (!element) {
    return;
  }

  element.classList.remove(className);
  void element.offsetWidth;
  element.classList.add(className);

  window.setTimeout(() => {
    element.classList.remove(className);
  }, duration);
}

function getRouteSelectionDuration() {
  return Number.parseFloat(
    getComputedStyle(document.documentElement).getPropertyValue("--tp-motion-route-selection"),
  ) || 620;
}

function scrollRouteIntoView() {
  const routeExperience = document.querySelector(".route-experience");
  if (!routeExperience) {
    return;
  }

  const targetTop = Math.max(
    0,
    Math.min(
      window.scrollY + routeExperience.getBoundingClientRect().top - 20,
      document.documentElement.scrollHeight - window.innerHeight,
    ),
  );

  if (reducedMotionQuery.matches || Math.abs(targetTop - window.scrollY) < 2) {
    window.scrollTo({ top: targetTop, behavior: "auto" });
    return;
  }

  if (routeScrollAnimationFrame !== null) {
    window.cancelAnimationFrame(routeScrollAnimationFrame);
  }

  const startTop = window.scrollY;
  const distance = targetTop - startTop;
  const duration = getRouteSelectionDuration();
  const startTime = performance.now();

  const step = (now) => {
    const progress = Math.min((now - startTime) / duration, 1);
    const easedProgress = 1 - Math.pow(1 - progress, 4);
    window.scrollTo({ top: startTop + distance * easedProgress, behavior: "auto" });

    if (progress < 1) {
      routeScrollAnimationFrame = window.requestAnimationFrame(step);
      return;
    }

    routeScrollAnimationFrame = null;
  };

  routeScrollAnimationFrame = window.requestAnimationFrame(step);
}

function scrollMapStageIntoView() {
  if (!mapStageFrame) {
    return;
  }

  const targetTop = Math.max(
    0,
    Math.min(
      window.scrollY + mapStageFrame.getBoundingClientRect().top - 12,
      document.documentElement.scrollHeight - window.innerHeight,
    ),
  );

  if (reducedMotionQuery.matches || Math.abs(targetTop - window.scrollY) < 2) {
    window.scrollTo({ top: targetTop, behavior: "auto" });
    return;
  }

  if (routeScrollAnimationFrame !== null) {
    window.cancelAnimationFrame(routeScrollAnimationFrame);
  }

  const startTop = window.scrollY;
  const distance = targetTop - startTop;
  const duration = getRouteSelectionDuration();
  const startTime = performance.now();

  const step = (now) => {
    const progress = Math.min((now - startTime) / duration, 1);
    const easedProgress = 1 - Math.pow(1 - progress, 4);
    window.scrollTo({ top: startTop + distance * easedProgress, behavior: "auto" });

    if (progress < 1) {
      routeScrollAnimationFrame = window.requestAnimationFrame(step);
      return;
    }

    routeScrollAnimationFrame = null;
  };

  routeScrollAnimationFrame = window.requestAnimationFrame(step);
}

function scrollPageToTop() {
  if (reducedMotionQuery.matches || window.scrollY < 2) {
    window.scrollTo({ top: 0, behavior: "auto" });
    return;
  }

  if (routeScrollAnimationFrame !== null) {
    window.cancelAnimationFrame(routeScrollAnimationFrame);
  }

  const startTop = window.scrollY;
  const duration = getRouteSelectionDuration();
  const startTime = performance.now();

  const step = (now) => {
    const progress = Math.min((now - startTime) / duration, 1);
    const easedProgress = 1 - Math.pow(1 - progress, 4);
    window.scrollTo({ top: startTop * (1 - easedProgress), behavior: "auto" });

    if (progress < 1) {
      routeScrollAnimationFrame = window.requestAnimationFrame(step);
      return;
    }

    routeScrollAnimationFrame = null;
  };

  routeScrollAnimationFrame = window.requestAnimationFrame(step);
}

function animateTranslatedContent() {
  const textTargets = [
    eyebrowText,
    introLeadText,
    introText,
    stopsTitle,
    stopsSubtitle,
    platformsEyebrow,
    shareTitle,
    detailTitle,
    detailDescription,
    miniPlayerTitle,
    miniPlayerSubtitle,
    brandNameEl,
    brandTagEl,
    landingTitle,
    mapStageNote,
    detailCopyTitle,
  ];

  textTargets.forEach((element) => {
    replayAnimationClass(element, "is-translating");
  });

  if (stopsList) {
    stopsList.querySelectorAll(".stop-title, .stop-meta, .stop-availability").forEach((element) => {
      replayAnimationClass(element, "is-translating");
    });
  }
}

function pulseActiveLanguageChips() {
  document.querySelectorAll(".language-chip.is-active").forEach((chip) => {
    replayAnimationClass(chip, "is-pulsing", 500);
  });
}

function pulseActiveStopCard(stopNumber = activeStopNumber) {
  const activeButton = buttonsByStop.get(stopNumber);
  replayAnimationClass(activeButton, "is-pulsing", Math.min(getRouteSelectionDuration(), 560));
}

function clearRouteSelectionTimers() {
  routeSelectionTimers.forEach((timer) => window.clearTimeout(timer));
  routeSelectionTimers = [];
}

function scheduleRouteSelection(callback, delay) {
  const timer = window.setTimeout(() => {
    routeSelectionTimers = routeSelectionTimers.filter((item) => item !== timer);
    callback();
  }, delay);
  routeSelectionTimers.push(timer);
}

function animateRouteSelectionCard(stopNumber = activeStopNumber) {
  const activeButton = buttonsByStop.get(stopNumber);
  replayAnimationClass(activeButton, "is-route-selecting", getRouteSelectionDuration());
  pulseActiveStopCard(stopNumber);
}

function reactToTransport(group, reaction) {
  replayAnimationClass(group, `is-transport-${reaction}`, 420);
}

function highlightActiveMarker(stopNumber = activeStopNumber) {
  markersByStop.forEach((marker, numero) => {
    const isSelected = numero === stopNumber;
    marker.setZIndexOffset(isSelected ? 1000 : 0);

    const markerElement = marker.getElement()?.querySelector(".map-marker");
    if (!markerElement) {
      return;
    }

    markerElement.classList.toggle("is-selected", isSelected);
    markerElement.classList.remove("is-highlighted");

    if (isSelected) {
      void markerElement.offsetWidth;
      markerElement.classList.add("is-highlighted");
      window.setTimeout(() => {
        markerElement.classList.remove("is-highlighted");
      }, getRouteSelectionDuration() + 80);
    }
  });
}

function showMapSelectionLabel(tappa, marker) {
  if (!map || !marker) {
    return;
  }

  window.clearTimeout(mapSelectionTooltipFadeTimer);
  window.clearTimeout(mapSelectionTooltipCloseTimer);
  mapSelectionTooltip?.remove();

  const strings = getUiStrings(currentLanguage);
  const label = `${strings.stopLabel || "Tappa"} ${tappa.numero} · ${getStopTitle(tappa)}`;
  const content = document.createElement("span");
  content.className = "map-selection-label-content";
  const image = document.createElement("img");
  image.className = "map-selection-label-image";
  image.src = STOP_ARTWORKS[tappa.numero] || WHITE_ARTWORK;
  if (isMobileMapViewport()) {
    image.alt = getStopTitle(tappa);
    content.append(image);
  } else {
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    const title = document.createElement("span");
    title.className = "map-selection-label-title";
    title.textContent = label;
    content.append(image, title);
  }
  mapSelectionTooltip = L.tooltip({
    className: "map-selection-label",
    direction: "top",
    offset: [0, -22],
    opacity: 1,
    interactive: false,
  })
    .setLatLng(marker.getLatLng())
    .setContent(content)
    .addTo(map);

  window.requestAnimationFrame(() => {
    mapSelectionTooltip?.getElement()?.classList.remove("is-fading");
  });

  mapSelectionTooltipFadeTimer = window.setTimeout(() => {
    mapSelectionTooltip?.getElement()?.classList.add("is-fading");
  }, 3700);
  mapSelectionTooltipCloseTimer = window.setTimeout(() => {
    mapSelectionTooltip?.remove();
    mapSelectionTooltip = null;
  }, 4000);
}

function getStatusMessage(statusKey) {
  if (!statusKey) {
    return "";
  }

  const localizedStatusMessages = statusMessages[currentLanguage] || statusMessages.IT;
  return localizedStatusMessages[statusKey] || statusMessages.IT[statusKey] || "";
}

function setMapLoadStatusByKey(statusKey = "") {
  currentMapStatusKey = statusKey;

  if (!mapLoadStatus) {
    return;
  }

  if (!statusKey) {
    mapLoadStatus.textContent = "";
    mapLoadStatus.classList.remove("is-visible");
    return;
  }

  mapLoadStatus.textContent = getStatusMessage(statusKey);
  mapLoadStatus.classList.add("is-visible");
}

function setAudioFeedbackByKey(statusKey = "") {
  currentAudioStatusKey = statusKey;

  if (!audioFeedback) {
    return;
  }

  if (!statusKey) {
    audioFeedback.textContent = "";
    audioFeedback.classList.remove("is-visible");
    return;
  }

  audioFeedback.textContent = getStatusMessage(statusKey);
  audioFeedback.classList.add("is-visible");
}

function bindMapLoadFeedback(tileLayer) {
  if (!tileLayer) {
    return;
  }

  tileLayer.on("load", () => {
    hasMapLoadedTiles = true;
    tileErrorCount = 0;

    if (currentMapStatusKey === "mapLoadError" || currentMapStatusKey === "offlineStatus") {
      setMapLoadStatusByKey("");
    }
  });

  tileLayer.on("tileerror", () => {
    tileErrorCount += 1;

    if (tileErrorCount >= 2 || !hasMapLoadedTiles) {
      setMapLoadStatusByKey(navigator.onLine ? "mapLoadError" : "offlineStatus");
    }
  });

  window.addEventListener("offline", () => {
    setMapLoadStatusByKey("offlineStatus");
    if (currentAudio) {
      setAudioFeedbackByKey("offlineStatus");
    }
  });

  window.addEventListener("online", () => {
    if (currentMapStatusKey === "offlineStatus") {
      setMapLoadStatusByKey("");
    }

    if (currentAudioStatusKey === "offlineStatus") {
      setAudioFeedbackByKey("");
    }
  });
}

function consumeControlEvent(event) {
  if (!event) {
    return;
  }

  event.preventDefault();
  event.stopPropagation();
}

function stopControlPropagation(event) {
  if (!event) {
    return;
  }

  event.stopPropagation();
}

function syncMobileMapCaptionReservedSpace() {
  const root = document.documentElement;
  const isVisible = Boolean(
    mapLiveCaption &&
    isMobileMapViewport() &&
    !overlayOpen &&
    !document.body.classList.contains("player-open") &&
    !mapLiveCaption.hidden &&
    mapLiveCaption.classList.contains("is-visible"),
  );
  const captionHeight = isVisible ? Math.ceil(mapLiveCaption.getBoundingClientRect().height) : 0;
  const nextValue = `${captionHeight ? captionHeight + 16 : 0}px`;

  if (root.style.getPropertyValue("--mobile-map-caption-reserved-space").trim() !== nextValue) {
    root.style.setProperty("--mobile-map-caption-reserved-space", nextValue);
  }
}

function syncMiniPlayerReservedSpace() {
  const root = document.documentElement;
  const safeBuffer = 24;

  if (
    document.body.classList.contains("is-map-player-panel") &&
    window.matchMedia("(min-width: 1024px)").matches
  ) {
    root.style.setProperty("--mini-player-reserved-space", "0px");
    syncMobileMapCaptionReservedSpace();
    return;
  }

  if (!miniPlayer || miniPlayer.classList.contains("is-hidden")) {
    root.style.setProperty("--mini-player-reserved-space", `${118 + safeBuffer}px`);
    syncMobileMapCaptionReservedSpace();
    return;
  }

  const measuredHeight = Math.ceil(miniPlayer.getBoundingClientRect().height);
  const reservedSpace = Math.max(118, measuredHeight + safeBuffer);
  root.style.setProperty("--mini-player-reserved-space", `${reservedSpace}px`);
  syncMobileMapCaptionReservedSpace();
}

function bindMiniPlayerLayoutSync() {
  syncMiniPlayerReservedSpace();

  if (typeof ResizeObserver === "function" && miniPlayer && !miniPlayerResizeObserver) {
    miniPlayerResizeObserver = new ResizeObserver(() => {
      syncMiniPlayerReservedSpace();
      if (mapStageFrame.classList.contains("is-expanded")) {
        requestAnimationFrame(() => map.invalidateSize());
      }
    });
    miniPlayerResizeObserver.observe(miniPlayer);
  }

  window.addEventListener("resize", syncMiniPlayerReservedSpace);
  window.addEventListener("orientationchange", syncMiniPlayerReservedSpace);
  window.addEventListener("resize", () => window.requestAnimationFrame(syncMapLiveCaption));
  document.fonts?.ready.then(syncMapLiveCaption);
}

function syncMobileTranscriptSheetLayout() {
  if (!playerSheet || !playerTranscriptDock || !playerMobileLiveTranscript) {
    return;
  }

  const isMobile = window.matchMedia("(max-width: 1023px)").matches;
  if (!isMobile || playerOverlay?.classList.contains("is-map-panel")) {
    playerSheet.style.removeProperty("--mobile-transcript-left");
    playerSheet.style.removeProperty("--mobile-transcript-right");
    playerSheet.style.removeProperty("--mobile-transcript-top");
    playerSheet.style.removeProperty("--mobile-transcript-height");
    playerSheet.style.removeProperty("--mobile-transcript-bottom");
    playerSheet.style.removeProperty("--mobile-transcript-max-height");
    return;
  }

  const sheetRect = playerSheet.getBoundingClientRect();
  const sideRect = playerSide?.getBoundingClientRect();
  const metaRect = playerSide?.querySelector(".player-meta")?.getBoundingClientRect();
  const timelineRect = playerSide?.querySelector(".player-timeline")?.getBoundingClientRect();
  const commandRect = playerSide?.querySelector(".player-command-row")?.getBoundingClientRect();
  const navigationRect = playerStopNavigation?.getBoundingClientRect();

  if (!sideRect || !Number.isFinite(sheetRect.bottom) || !Number.isFinite(sideRect.bottom)) {
    return;
  }

  const protectedBottom = Math.max(
    metaRect?.bottom || 0,
    timelineRect?.bottom || 0,
    commandRect?.bottom || 0,
  );

  if (navigationRect && navigationRect.height > 0) {
    const navigationTop = Math.max(navigationRect.top, protectedBottom + 6);
    const visibleNavigationCards = [playerPreviousPreview, playerNextPreview].filter(
      (card) => card && !card.hidden,
    );
    const singleCardRect =
      visibleNavigationCards.length === 1
        ? visibleNavigationCards[0].getBoundingClientRect()
        : null;
    const navigationStyles = playerStopNavigation
      ? window.getComputedStyle(playerStopNavigation)
      : null;
    const navigationGap =
      Number.parseFloat(navigationStyles?.rowGap || navigationStyles?.gap || "0") || 0;
    const equivalentTwoCardHeight =
      singleCardRect && singleCardRect.height > 0
        ? singleCardRect.height * 2 + navigationGap
        : navigationRect.height;
    const desiredNavigationHeight =
      visibleNavigationCards.length === 1
        ? equivalentTwoCardHeight
        : navigationRect.height;
    const maxAvailableHeight = Math.max(
      navigationRect.height,
      sheetRect.bottom - navigationTop - 8,
    );
    const navigationHeight = Math.max(
      navigationRect.height,
      Math.min(desiredNavigationHeight, maxAvailableHeight),
    );
    const leftOffset = Math.max(0, navigationRect.left - sheetRect.left);
    const rightOffset = Math.max(0, sheetRect.right - navigationRect.right);
    const topOffset = Math.max(0, navigationTop - sheetRect.top);

    playerSheet.style.setProperty("--mobile-transcript-left", `${Math.round(leftOffset)}px`);
    playerSheet.style.setProperty("--mobile-transcript-right", `${Math.round(rightOffset)}px`);
    playerSheet.style.setProperty("--mobile-transcript-top", `${Math.round(topOffset)}px`);
    playerSheet.style.setProperty("--mobile-transcript-height", `${Math.round(navigationHeight)}px`);
    playerSheet.style.removeProperty("--mobile-transcript-bottom");
    playerSheet.style.removeProperty("--mobile-transcript-max-height");
    return;
  }

  const contentBottom = Math.min(sheetRect.bottom, sideRect.bottom);
  const bottomOffset = Math.max(0, sheetRect.bottom - contentBottom);
  const availableHeight = Math.max(84, contentBottom - protectedBottom - 12);
  const fallbackHeight = Math.max(84, Math.min(190, availableHeight));

  playerSheet.style.removeProperty("--mobile-transcript-top");
  playerSheet.style.removeProperty("--mobile-transcript-height");
  playerSheet.style.removeProperty("--mobile-transcript-left");
  playerSheet.style.removeProperty("--mobile-transcript-right");
  playerSheet.style.setProperty("--mobile-transcript-bottom", `${Math.round(bottomOffset)}px`);
  playerSheet.style.setProperty("--mobile-transcript-max-height", `${Math.round(fallbackHeight)}px`);
}

function syncMobileMapDockHeight() {
  if (!isMobileMapPlayerMode() || !playerSheet) return;
  const height = playerSheet.offsetHeight;
  if (height > 0) {
    document.documentElement.style.setProperty("--mobile-map-player-dock-height", `${height}px`);
  }
}

function bindMobileTranscriptLayoutSync() {
  syncMobileTranscriptSheetLayout();

  if (typeof ResizeObserver === "function" && !mobileTranscriptLayoutResizeObserver) {
    mobileTranscriptLayoutResizeObserver = new ResizeObserver(() => {
      window.requestAnimationFrame(() => {
        syncMobileTranscriptSheetLayout();
        syncMobileMapDockHeight();
      });
    });
    [playerSheet, playerSide, playerStopNavigation]
      .filter(Boolean)
      .forEach((element) => mobileTranscriptLayoutResizeObserver.observe(element));
  }

  window.addEventListener("resize", syncMobileTranscriptSheetLayout);
  window.addEventListener("resize", syncMobileMapDockHeight);
  window.addEventListener("orientationchange", syncMobileTranscriptSheetLayout);
}

function recenterMapToRoute({ preserveZoom = false } = {}) {
  if (!routeBounds?.isValid()) {
    return;
  }

  const isDesktopMapPanel =
    document.body.classList.contains("is-map-player-panel") &&
    window.matchMedia("(min-width: 1024px)").matches;
  const mapPadding = isMapFullscreenActive() ? 52 : 40;

  if (preserveZoom) {
    map.flyTo(routeBounds.getCenter(), map.getZoom(), {
      animate: !reducedMotionQuery.matches,
      duration: reducedMotionQuery.matches ? 0 : 0.65,
    });
    return;
  }

  map.flyToBounds(routeBounds, {
    animate: !reducedMotionQuery.matches,
    duration: reducedMotionQuery.matches ? 0 : 0.65,
    paddingTopLeft: isDesktopMapPanel ? [156, mapPadding] : [mapPadding, mapPadding],
    paddingBottomRight: [mapPadding, mapPadding],
  });
}

function focusMapOnSelectedRouteSegment() {
  const segmentBounds = activeRouteLayer?.getBounds?.();
  const bounds = segmentBounds?.isValid?.() ? segmentBounds : routeBounds;
  if (!bounds?.isValid?.()) {
    return false;
  }

  const isDesktopMapPanel = shouldKeepRouteCenteredInDesktopMapPanel();
  const mapPadding = isMapFullscreenActive() ? 52 : 40;
  map.flyToBounds(bounds, {
    animate: !reducedMotionQuery.matches,
    duration: reducedMotionQuery.matches ? 0 : 0.82,
    maxZoom: 17,
    paddingTopLeft: isDesktopMapPanel ? [156, mapPadding] : [mapPadding, mapPadding],
    paddingBottomRight: [mapPadding, mapPadding],
  });
  return true;
}

function getResponsiveCameraPreset(tappa, presetName) {
  const preset = mapCameraPresets[tappa.numero]?.[presetName];
  if (!preset) {
    return null;
  }

  // The mobile map has less usable width and a persistent player overlay. A
  // slightly wider camera avoids asking Leaflet to correct the target at the
  // end of the animation, while desktop keeps the close editorial framing.
  const mobileZoomAdjustment = isMobileMapViewport() ? -0.2 : 0;
  return {
    center: [...preset.center],
    zoom: preset.zoom + mobileZoomAdjustment,
  };
}

function clampMapCameraCenter(center, zoom) {
  const maxBounds = typeof map.getMaxBounds === "function" ? map.getMaxBounds() : map.options.maxBounds;
  if (!maxBounds?.isValid?.()) {
    return L.latLng(center[0], center[1]);
  }

  const mapSize = map.getSize();
  const northWest = map.project(maxBounds.getNorthWest(), zoom);
  const southEast = map.project(maxBounds.getSouthEast(), zoom);
  const requested = map.project(L.latLng(center[0], center[1]), zoom);
  const halfWidth = mapSize.x / 2;
  const halfHeight = mapSize.y / 2;
  const minX = northWest.x + halfWidth;
  const maxX = southEast.x - halfWidth;
  const minY = northWest.y + halfHeight;
  const maxY = southEast.y - halfHeight;
  const clampAxis = (value, minimum, maximum, fallback) =>
    minimum > maximum ? fallback : Math.max(minimum, Math.min(maximum, value));

  const clamped = L.point(
    clampAxis(requested.x, minX, maxX, (northWest.x + southEast.x) / 2),
    clampAxis(requested.y, minY, maxY, (northWest.y + southEast.y) / 2),
  );
  return map.unproject(clamped, zoom);
}

function canCenterMapCameraAt(center, zoom) {
  const maxBounds = typeof map.getMaxBounds === "function" ? map.getMaxBounds() : map.options.maxBounds;
  if (!maxBounds?.isValid?.()) {
    return true;
  }

  const mapSize = map.getSize();
  const northWest = map.project(maxBounds.getNorthWest(), zoom);
  const southEast = map.project(maxBounds.getSouthEast(), zoom);
  // `center` can be either the preset array or the L.LatLng returned after
  // shifting the camera into the visible map area. Normalize both shapes
  // before asking Leaflet to project them.
  const requested = map.project(L.latLng(center), zoom);
  const halfWidth = mapSize.x / 2;
  const halfHeight = mapSize.y / 2;

  return (
    northWest.x + halfWidth <= southEast.x - halfWidth &&
    northWest.y + halfHeight <= southEast.y - halfHeight &&
    requested.x >= northWest.x + halfWidth &&
    requested.x <= southEast.x - halfWidth &&
    requested.y >= northWest.y + halfHeight &&
    requested.y <= southEast.y - halfHeight
  );
}

function getMapVisibleAreaOffset() {
  if (!map) {
    return L.point(0, 0);
  }

  const mapRect = map.getContainer().getBoundingClientRect();
  if (!mapRect.width || !mapRect.height) {
    return L.point(0, 0);
  }

  let visibleTop = mapRect.top;
  let visibleRight = mapRect.right;
  let visibleBottom = mapRect.bottom;
  let visibleLeft = mapRect.left;
  const blockers = isMobileMapPlayerMode()
    ? [playerSheet, mapLiveCaption, mapExploreMascotImage?.closest(".map-explore-mascot")]
    : [miniPlayer, mapExploreStop, mapLiveCaption, playerOverlay];

  blockers.forEach((blocker) => {
    if (!blocker || blocker.hidden || blocker.classList.contains("is-hidden")) {
      return;
    }

    const rect = blocker.getBoundingClientRect();
    const overlapsMap = rect.right > mapRect.left && rect.left < mapRect.right &&
      rect.bottom > mapRect.top && rect.top < mapRect.bottom;
    if (!overlapsMap) {
      return;
    }

    if (rect.top > mapRect.top && rect.bottom >= mapRect.bottom - 1) {
      visibleBottom = Math.min(visibleBottom, rect.top);
    } else if (rect.left > mapRect.left && rect.right >= mapRect.right - 1) {
      visibleRight = Math.min(visibleRight, rect.left);
    } else if (rect.bottom < mapRect.bottom && rect.top <= mapRect.top + 1) {
      visibleTop = Math.max(visibleTop, rect.bottom);
    } else {
      // A bottom sheet/caption that floats inside the map still reserves the
      // lower portion: keeping its top edge clear is safer than centering
      // underneath translucent content.
      visibleBottom = Math.min(visibleBottom, rect.top);
    }
  });

  const visibleCenter = L.point(
    (Math.max(visibleLeft, mapRect.left) + Math.min(visibleRight, mapRect.right)) / 2,
    (Math.max(visibleTop, mapRect.top) + Math.min(visibleBottom, mapRect.bottom)) / 2,
  );
  return visibleCenter.subtract(L.point(mapRect.left + mapRect.width / 2, mapRect.top + mapRect.height / 2));
}

function shiftMapCameraCenterIntoVisibleArea(center, zoom) {
  const offset = getMapVisibleAreaOffset();
  if (!offset.x && !offset.y) {
    return L.latLng(center[0], center[1]);
  }

  const projectedCenter = map.project(L.latLng(center[0], center[1]), zoom);
  return map.unproject(projectedCenter.subtract(offset), zoom);
}

function getFeasibleCameraZoom(center, requestedZoom) {
  const maxZoom = Math.min(map.getMaxZoom?.() || 22, 22);
  // Leaflet snaps flyTo's zoom to this step. Computing the target center at
  // an unsnapped zoom can move a marker far outside the viewport after flyTo.
  const zoomStep = map.options.zoomSnap > 0 ? map.options.zoomSnap : 0.25;
  const firstZoom = Math.ceil((requestedZoom - 1e-8) / zoomStep) * zoomStep;
  for (let zoom = firstZoom; zoom <= maxZoom; zoom += zoomStep) {
    if (canCenterMapCameraAt(center, zoom)) {
      return Number(zoom.toFixed(2));
    }
  }
  return maxZoom;
}

function getStopCameraTarget(tappa, presetName) {
  const preset = getResponsiveCameraPreset(tappa, presetName);
  if (!preset) {
    return null;
  }

  // A stop always returns to its authored framing, even after the visitor
  // zoomed in elsewhere. Reusing the current zoom could crop the route.
  const requestedZoom = preset.zoom;
  const visibleCenter = shiftMapCameraCenterIntoVisibleArea(preset.center, requestedZoom);
  const targetZoom = getFeasibleCameraZoom(visibleCenter, requestedZoom);
  const adjustedCenter = shiftMapCameraCenterIntoVisibleArea(preset.center, targetZoom);
  const target = {
    center: clampMapCameraCenter([adjustedCenter.lat, adjustedCenter.lng], targetZoom),
    zoom: targetZoom,
  };

  if (isStopVisibleAtCameraTarget(tappa, target)) {
    return target;
  }

  // A contextual preset must never leave its selected marker outside the
  // unobstructed map. Keep the authored zoom where possible, but fall back to
  // the same stop-centered framing used by the other selection paths.
  const stopCenter = [tappa.latitudine, tappa.longitudine];
  const maxZoom = Math.min(map.getMaxZoom?.() || 22, 22);
  const zoomStep = map.options.zoomSnap > 0 ? map.options.zoomSnap : 0.25;
  const firstZoom = Math.ceil((targetZoom - 1e-8) / zoomStep) * zoomStep;

  // Recompute the offset center at each candidate zoom. The available-area
  // shift changes in map pixels as zoom changes, and clamping a shifted center
  // afterward can otherwise push an edge stop (especially stop 1 on mobile)
  // back underneath the top edge of the map.
  for (let zoom = firstZoom; zoom <= maxZoom; zoom += zoomStep) {
    const shiftedStop = shiftMapCameraCenterIntoVisibleArea(stopCenter, zoom);
    if (!canCenterMapCameraAt(shiftedStop, zoom)) {
      continue;
    }

    const center = clampMapCameraCenter([shiftedStop.lat, shiftedStop.lng], zoom);
    const fallback = { center, zoom: Number(zoom.toFixed(2)) };
    if (isStopVisibleAtCameraTarget(tappa, fallback)) {
      return fallback;
    }
  }

  const safeZoom = maxZoom;
  const safeCenter = shiftMapCameraCenterIntoVisibleArea(stopCenter, safeZoom);
  return {
    center: clampMapCameraCenter([safeCenter.lat, safeCenter.lng], safeZoom),
    zoom: safeZoom,
  };
}

function isStopVisibleAtCameraTarget(tappa, target) {
  const size = map.getSize();
  const offset = getMapVisibleAreaOffset();
  const centerPoint = map.project(target.center, target.zoom);
  const markerPoint = map.project(L.latLng(tappa.latitudine, tappa.longitudine), target.zoom)
    .subtract(centerPoint)
    .add(size.divideBy(2));
  const margin = 36;
  const visibleLeft = Math.max(0, 2 * offset.x) + margin;
  const visibleRight = Math.min(size.x, size.x + 2 * offset.x) - margin;
  const visibleTop = Math.max(0, 2 * offset.y) + margin;
  const visibleBottom = Math.min(size.y, size.y + 2 * offset.y) - margin;

  return markerPoint.x >= visibleLeft && markerPoint.x <= visibleRight &&
    markerPoint.y >= visibleTop && markerPoint.y <= visibleBottom;
}

function isMapAtCameraPreset(target) {
  if (!map || !target?.center) {
    return false;
  }

  return map.getCenter().distanceTo(target.center) <= 18 && Math.abs(map.getZoom() - target.zoom) <= 0.05;
}

function flyToStopCameraPreset(tappa, presetName) {
  const target = getStopCameraTarget(tappa, presetName);
  if (!target || isMapAtCameraPreset(target)) {
    return false;
  }

  // Leaflet's easing parameter gives the camera a short emphasized
  // deceleration without adding a second correction or a bounce at moveend.
  map.stop();
  map.flyTo(target.center, target.zoom, {
    animate: !reducedMotionQuery.matches,
    duration: reducedMotionQuery.matches ? 0 : 0.58,
    easeLinearity: 0.14,
  });
  return true;
}

function getStopFocusZoom(tappa) {
  // Start from the actual zoom. When the map is very wide, the loop below
  // finds the first useful level at which the selected stop can be centered
  // without Leaflet applying a second max-bounds correction at moveend.
  const currentZoom = map.getZoom();
  const maxBounds = typeof map.getMaxBounds === "function" ? map.getMaxBounds() : map.options.maxBounds;

  if (!maxBounds?.isValid?.()) {
    return currentZoom;
  }

  const target = L.latLng(tappa.latitudine, tappa.longitudine);
  const mapSize = map.getSize();
  const edgePadding = 18;
  const maxZoom = Math.min(map.getMaxZoom?.() || 22, 22);

  // Find the least zoomed-in view in which the target can be the true map
  // center without Leaflet clamping it back to maxBounds at the end.
  for (let zoom = currentZoom; zoom <= maxZoom; zoom += 0.25) {
    const projectedTarget = map.project(target, zoom);
    const projectedNorthWest = map.project(maxBounds.getNorthWest(), zoom);
    const projectedSouthEast = map.project(maxBounds.getSouthEast(), zoom);
    const halfWidth = mapSize.x / 2 - edgePadding;
    const halfHeight = mapSize.y / 2 - edgePadding;
    const minCenterX = projectedNorthWest.x + halfWidth;
    const maxCenterX = projectedSouthEast.x - halfWidth;
    const minCenterY = projectedNorthWest.y + halfHeight;
    const maxCenterY = projectedSouthEast.y - halfHeight;

    if (
      minCenterX <= maxCenterX &&
      minCenterY <= maxCenterY &&
      projectedTarget.x >= minCenterX &&
      projectedTarget.x <= maxCenterX &&
      projectedTarget.y >= minCenterY &&
      projectedTarget.y <= maxCenterY
    ) {
      return zoom;
    }
  }

  return maxZoom;
}

function isMobileMapViewport() {
  return window.matchMedia("(max-width: 1023px)").matches;
}

function isMobileMapPlayerMode() {
  return Boolean(playerOverlay?.classList.contains("is-mobile-map-player"));
}

function updatePlayerMapButtonPresentation() {
  if (!playerMapButton) return;
  const strings = getUiStrings(currentLanguage);
  const isMapMode = isMobileMapPlayerMode();
  const label = isMapMode ? strings.playerSwitchToListen : strings.playerSwitchToMap;
  if (playerMapButtonIcon) {
    playerMapButtonIcon.textContent = isMapMode ? "headphones" : "map";
  }
  playerMapButton.setAttribute("aria-label", label);
  playerMapButton.title = label;
}

