function getGuideSteps() {
  const strings = getUiStrings(currentLanguage);
  const steps = [{ target: mapStageFrame, text: strings.guideMap }];

  if (!window.matchMedia("(min-width: 1024px)").matches) {
    steps.push({ target: mapRecenterButton, text: strings.guideLocation });
    steps.push({ target: mapDirectionsButton, text: strings.guideDirections });
  }

  steps.push(
    { target: getStopsGuideTarget(), text: strings.guideStops, placement: "stopsTitleRight" },
    { target: miniPlayer, text: strings.guidePlayer },
  );

  if (window.matchMedia("(min-width: 1024px)").matches) {
    steps.push({
      target: miniPlayerExpand || miniPlayer,
      text: strings.guideExplore,
      placement: "miniPlayerExpand",
      guideTransitionAction: "expand",
    });
    steps.push({
      target: mapStageFrame,
      text: strings.guideExploreView,
      opensFullPlayer: true,
      placement: "exploreMapBottom",
      guideTransitionAction: "close",
    });
    return steps;
  }

  steps.push({
    target: getFullPlayerGuideTarget(),
    highlightTarget: playerSheet,
    text: strings.guideFullPlayer,
    opensFullPlayer: true,
    playerMode: "map",
    highlight: false,
    floatingPlacement: "fullPlayerTop",
  });
  steps.push({
    target: playerMapButton,
    highlightTarget: playerMapButton,
    text: strings.guidePlayerMapToggle,
    opensFullPlayer: true,
    playerMode: "map",
    floatingPlacement: "fullPlayerTop",
  });
  steps.push({
    target: playerSheet,
    highlightTarget: playerSheet,
    text: strings.guideListeningView,
    opensFullPlayer: true,
    playerMode: "listen",
    floatingPlacement: "fullPlayerBottom",
  });
  steps.push({
    target: playerMapButton,
    highlightTarget: playerMapButton,
    text: strings.guideReturnToMap,
    opensFullPlayer: true,
    playerMode: "listen",
    floatingPlacement: "fullPlayerBottom",
  });
  steps.push({
    target: playerCloseButton,
    highlightTarget: playerCloseButton,
    text: strings.guideClosePlayer,
    opensFullPlayer: true,
    playerMode: "map",
    floatingPlacement: "fullPlayerTop",
    guideTransitionAction: "closePlayer",
  });
  return steps;
}

function getGuideSafeBottom() {
  if (overlayOpen) {
    return window.innerHeight - 18;
  }

  const miniPlayerTop = miniPlayer?.getBoundingClientRect().top;
  if (Number.isFinite(miniPlayerTop)) {
    return miniPlayerTop - 18;
  }

  return window.innerHeight - 18;
}

function renderGuideStepAfterExploreLayout() {
  const startedAt = performance.now();
  const waitForLayout = () => {
    if (!guideLayer || guideLayer.classList.contains("is-hidden")) {
      return;
    }

    const target = getFullPlayerGuideTarget();
    const targetRect = target?.getBoundingClientRect();
    const layoutReady =
      isMapFullscreenActive() &&
      overlayOpen &&
      playerOverlay?.classList.contains("is-map-panel") &&
      targetRect?.width > 0 &&
      targetRect?.height > 0;

    if (layoutReady || performance.now() - startedAt >= 1200) {
      renderGuideStep();
      return;
    }

    window.requestAnimationFrame(waitForLayout);
  };

  window.requestAnimationFrame(waitForLayout);
}

function scrollGuideTargetIntoView(target) {
  if (!target || target === document.body) {
    return;
  }

  if (
    target === miniPlayer ||
    target === playerOverlay ||
    target === playerSheet ||
    target.closest?.("#player-overlay")
  ) {
    return;
  }

  const rect = target.getBoundingClientRect();
  const safeTop = 18;
  const safeBottom = Math.max(180, getGuideSafeBottom());
  const targetTop = rect.top + window.scrollY;
  const isStopsPanelGuide = target === stopsPanel;
  const isSectionGuideOnMobile =
    target.matches?.(".stops-panel, .platforms-panel, .share-panel") &&
    window.matchMedia("(max-width: 760px)").matches;

  if (isStopsPanelGuide) {
    const cardHeight = guideCard?.offsetHeight || 160;
    const desiredTop = window.matchMedia("(max-width: 760px)").matches
      ? Math.min(safeBottom - 32, Math.max(220, cardHeight + 32))
      : Math.max(safeTop, cardHeight + 32);
    const nextScrollTop = Math.max(0, targetTop - desiredTop);
    if (Math.abs(nextScrollTop - window.scrollY) > 10) {
      window.scrollTo({ top: nextScrollTop, behavior: "auto" });
    }
    return;
  }

  if (isSectionGuideOnMobile) {
    const nextScrollTop = Math.max(0, targetTop - safeTop);
    if (Math.abs(nextScrollTop - window.scrollY) > 10) {
      window.scrollTo({ top: nextScrollTop, behavior: "auto" });
    }
    return;
  }

  const targetCenter = targetTop + rect.height / 2;
  const safeCenter = safeTop + (safeBottom - safeTop) / 2;
  const nextScrollTop = Math.max(0, targetCenter - safeCenter);

  if (Math.abs(nextScrollTop - window.scrollY) > 10) {
    window.scrollTo({ top: nextScrollTop, behavior: "auto" });
  }
}

function positionFullPlayerGuideCard(step = null) {
  if (!guideCard) {
    return;
  }

  clearGuidePointer();
  guideCard.classList.remove("is-above-guide-target");
  guideCard.classList.remove("is-stops-title-guide");
  guideCard.style.removeProperty("--guide-card-mobile-top");

  const sheetRect = (playerSheet || playerOverlay || document.body).getBoundingClientRect();
  const safeLeft = Math.max(16, sheetRect.left + 16);
  const safeRight = Math.min(window.innerWidth - 16, sheetRect.right - 16);
  const cardWidth = Math.min(420, window.innerWidth - 32);
  const cardHeight = guideCard.offsetHeight || 190;
  const isMobile = window.matchMedia("(max-width: 760px)").matches;
  const availableWidth = Math.max(cardWidth, safeRight - safeLeft);
  const preferredLeft = isMobile
    ? safeLeft + (availableWidth - cardWidth) / 2
    : safeLeft + Math.max(0, (availableWidth - cardWidth) * 0.58);
  const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
  const preferredTop = step?.floatingPlacement === "fullPlayerBottom"
    ? window.innerHeight - cardHeight - 16
    : isMobileMapViewport() ? 16 : Math.max(16, sheetRect.top + 16);
  const top = Math.max(16, Math.min(window.innerHeight - cardHeight - 16, preferredTop));

  guideCard.style.setProperty("--guide-floating-left", `${left}px`);
  guideCard.style.setProperty("--guide-floating-top", `${top}px`);
  guideCard.style.left = `${left}px`;
  guideCard.style.top = `${top}px`;
}

function positionGuideCard(target, step = null) {
  if (!guideCard || !target) {
    return;
  }

  guideCard.classList.remove("is-mobile-directions-guide");
  guideCard.classList.remove("is-above-guide-target");
  const isFloatingFullPlayerStep = ["fullPlayerTop", "fullPlayerBottom"].includes(step?.floatingPlacement);
  guideCard.classList.toggle("is-floating-guide-card", isFloatingFullPlayerStep);
  if (isFloatingFullPlayerStep) {
    positionFullPlayerGuideCard(step);
    return;
  }

  guideCard.style.removeProperty("--guide-floating-left");
  guideCard.style.removeProperty("--guide-floating-top");

  const rect = target.getBoundingClientRect();
  const cardWidth = Math.min(360, window.innerWidth - 32);
  const isMobile = window.matchMedia("(max-width: 760px)").matches;
  const isMiniPlayerGuideTarget = target === miniPlayer;
  const isDirectionsGuideTarget = target === mapDirectionsButton;
  const isStopsTitleGuideTarget = step?.placement === "stopsTitleRight";
  const isMiniPlayerExpandGuideTarget = step?.placement === "miniPlayerExpand";
  const isExploreMapGuideTarget = step?.placement === "exploreMapBottom";
  const isPlayerCloseGuideTarget = step?.placement === "playerClose";
  guideCard.classList.toggle("is-mobile-directions-guide", isMobile && isDirectionsGuideTarget);
  guideCard.classList.toggle("is-stops-title-guide", isStopsTitleGuideTarget);
  const cardHeight = guideCard.offsetHeight || 190;

  if (isExploreMapGuideTarget) {
    const gap = 24;
    const preferredLeft = rect.left + (rect.width - cardWidth) / 2;
    const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
    const top = Math.max(16, rect.bottom - cardHeight - gap);
    guideCard.style.left = `${left}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, "up", true);
    return;
  }

  if (isMiniPlayerExpandGuideTarget) {
    const gap = 16;
    const top = Math.max(16, rect.top - cardHeight - gap);
    const preferredLeft = rect.right - cardWidth + 22;
    const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
    guideCard.style.left = `${left}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, "down", true);
    return;
  }

  if (isPlayerCloseGuideTarget) {
    const gap = 20;
    const left = Math.max(16, rect.left - cardWidth - gap);
    const maxTop = Math.max(16, getGuideSafeBottom() - cardHeight);
    const preferredTop = rect.top + rect.height / 2 - cardHeight / 2;
    const top = Math.max(16, Math.min(maxTop, preferredTop));
    guideCard.style.left = `${left}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, "right", true);
    return;
  }

  if (isMiniPlayerGuideTarget) {
    const safeGap = 16;
    const availableAbovePlayer = Math.max(0, rect.top - safeGap * 2);
    const top = availableAbovePlayer >= cardHeight
      ? Math.max(safeGap, rect.top - cardHeight - safeGap)
      : safeGap;
    const preferredLeft = rect.left + Math.min(rect.width * 0.58, rect.width - cardWidth);
    const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
    guideCard.classList.add("is-above-guide-target");
    guideCard.style.setProperty("--guide-card-mobile-top", `${top}px`);
    guideCard.style.left = `${left}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, "down");
    return;
  }

  if (isStopsTitleGuideTarget) {
    const gap = 16;
    syncStopsGuideHighlight();
    const top = Math.max(16, rect.top - cardHeight - gap);
    const preferredLeft = rect.left + rect.width / 2 - cardWidth / 2;
    const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
    if (isMobile) {
      guideCard.classList.add("is-above-guide-target");
      guideCard.style.setProperty("--guide-card-mobile-top", `${top}px`);
    }
    guideCard.style.left = `${left}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, "down", true);
    return;
  }

  const shouldPlaceAboveTarget =
    target.matches?.(".platforms-panel, .share-panel") &&
    isMobile;

  guideCard.classList.toggle("is-above-guide-target", shouldPlaceAboveTarget);
  if (shouldPlaceAboveTarget) {
    guideCard.style.setProperty(
      "--guide-card-mobile-top",
      `${Math.max(16, rect.top - cardHeight - 16)}px`,
    );
    updateGuidePointer(target);
    return;
  }

  guideCard.style.removeProperty("--guide-card-mobile-top");
  const safeBottom = Math.max(190, getGuideSafeBottom());
  if (isDirectionsGuideTarget) {
    const gap = 16;
    const canPlaceLeft = rect.left - gap >= cardWidth;
    const canPlaceRight = window.innerWidth - rect.right - gap >= cardWidth;
    const maxTop = Math.max(16, safeBottom - cardHeight);

    if (!isMobile && (canPlaceLeft || canPlaceRight)) {
      // Keep the directions explanation on the right when both sides are free.
      const placeRight = canPlaceRight;
      const left = placeRight ? rect.right + gap : rect.left - cardWidth - gap;
      const top = Math.max(16, Math.min(maxTop, rect.top));
      guideCard.style.left = `${left}px`;
      guideCard.style.top = `${top}px`;
      updateGuidePointer(target, placeRight ? "left" : "right", true);
      return;
    }

    const belowTop = rect.bottom + 12;
    const aboveTop = rect.top - cardHeight - 12;
    const canPlaceBelow = belowTop + cardHeight <= safeBottom;
    const canPlaceAbove = aboveTop >= 16;
    const placeBelow = canPlaceBelow || !canPlaceAbove;
    const top = placeBelow
      ? Math.max(16, Math.min(maxTop, belowTop))
      : Math.max(16, aboveTop);

    if (isMobile) {
      guideCard.style.setProperty("--guide-card-mobile-top", `${top}px`);
    }
    guideCard.style.left = `${Math.max(16, Math.min(window.innerWidth - cardWidth - 16, rect.left))}px`;
    guideCard.style.top = `${top}px`;
    updateGuidePointer(target, placeBelow ? "up" : "down", isMobile);
    return;
  }

  const preferredLeft = rect.left + Math.min(rect.width * 0.58, rect.width - cardWidth);
  const left = Math.max(16, Math.min(window.innerWidth - cardWidth - 16, preferredLeft));
  const maxTop = Math.max(16, safeBottom - cardHeight);
  const preferredTop = rect.top + Math.min(24, Math.max(0, rect.height * 0.15));
  const top = Math.max(16, Math.min(maxTop, preferredTop));
  guideCard.style.left = `${left}px`;
  guideCard.style.top = `${top}px`;
  updateGuidePointer(target);
}

function updateGuidePointer(target, forcedDirection = null, alignPointerToTarget = false) {
  if (!guideCard || !target) {
    return;
  }

  const cardRect = guideCard.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const cardCenterX = cardRect.left + cardRect.width / 2;
  const cardCenterY = cardRect.top + cardRect.height / 2;
  const targetCenterX = targetRect.left + targetRect.width / 2;
  const targetCenterY = targetRect.top + targetRect.height / 2;
  const deltaX = targetCenterX - cardCenterX;
  const deltaY = targetCenterY - cardCenterY;
  clearGuidePointer();
  guideCard.style.removeProperty("--guide-pointer-x");
  guideCard.style.removeProperty("--guide-pointer-y");
  document.documentElement.style.setProperty("--guide-spotlight-x", `${targetCenterX}px`);
  document.documentElement.style.setProperty("--guide-spotlight-y", `${targetCenterY}px`);

  if (alignPointerToTarget && (forcedDirection === "up" || forcedDirection === "down")) {
    const pointerX = Math.max(18, Math.min(cardRect.width - 18, targetCenterX - cardRect.left));
    guideCard.style.setProperty("--guide-pointer-x", `${pointerX}px`);
  }

  if (alignPointerToTarget && (forcedDirection === "left" || forcedDirection === "right")) {
    const pointerY = Math.max(18, Math.min(cardRect.height - 18, targetCenterY - cardRect.top));
    guideCard.style.setProperty("--guide-pointer-y", `${pointerY}px`);
  }

  if (forcedDirection) {
    guideCard.classList.add(`is-pointing-${forcedDirection}`);
    return;
  }

  if (Math.abs(deltaX) > Math.abs(deltaY)) {
    guideCard.classList.add(deltaX > 0 ? "is-pointing-right" : "is-pointing-left");
    return;
  }

  guideCard.classList.add(deltaY > 0 ? "is-pointing-down" : "is-pointing-up");
}

function renderGuideStep() {
  if (!guideLayer || !guideStepText || !guideSkipButton || !guidePrevButton || !guideNextButton) {
    return;
  }

  const steps = getGuideSteps();
  const step = steps[activeGuideStepIndex];
  if (step?.opensFullPlayer && !overlayOpen) {
    guideOpenedPlayerOverlay = true;
    openPlayerOverlay(miniPlayer || helpButton || document.activeElement, { keepGuideOpen: true });
  }
  if (step?.playerMode && isMobileMapViewport() && overlayOpen &&
      isMobileMapPlayerMode() !== (step.playerMode === "map")) {
    setMobileMapPlayerMode(step.playerMode === "map");
  }
  const guideTarget = step?.target || (step?.opensFullPlayer ? getFullPlayerGuideTarget() : document.body);
  const strings = getUiStrings(currentLanguage);
  clearGuideHighlight();
  document.body.classList.toggle(
    "guide-map-control-focus",
    guideTarget === mapRecenterButton || guideTarget === mapDirectionsButton,
  );
  document.body.classList.toggle(
    "guide-map-intro-focus",
    activeGuideStepIndex === 0 && guideTarget === mapStageFrame,
  );
  document.body.classList.toggle(
    "guide-mini-player-expand-focus",
    guideTarget === miniPlayerExpand,
  );
  window.cancelAnimationFrame(guidePositionFrame);
  window.clearTimeout(guidePositionTimer);
  window.clearTimeout(guideArrivalTimer);
  window.clearTimeout(guideExploreTransitionTimer);
  guidePositionFrame = null;
  guidePositionTimer = null;
  guideArrivalTimer = null;
  guideExploreTransitionTimer = null;
  isGuideExploreTransitionRunning = false;
  guideCard.classList.remove("is-arriving");
  guideCard.classList.add("is-repositioning");
  if (step?.highlight !== false || step?.highlightTarget) {
    const highlightTarget = step?.highlightTarget || guideTarget;
    highlightTarget?.classList.add("is-guide-highlighted");
  }
  guideStepText.textContent = step.text;
  const isFirstGuideStep = activeGuideStepIndex === 0;
  const isLastGuideStep = activeGuideStepIndex === steps.length - 1;
  const prevGuideLabel = strings.guideBack || "Indietro";
  const nextGuideLabel = isLastGuideStep ? strings.guideDone : strings.guideNext;
  guideSkipButton.textContent = "×";
  guideSkipButton.setAttribute("aria-label", strings.guideSkip);
  guideSkipButton.title = strings.guideSkip;
  guidePrevButton.textContent = "←";
  guidePrevButton.disabled = isFirstGuideStep;
  guidePrevButton.classList.toggle("is-disabled", isFirstGuideStep);
  guidePrevButton.setAttribute("aria-label", prevGuideLabel);
  guidePrevButton.title = prevGuideLabel;
  guideNextButton.textContent = isLastGuideStep ? "✓" : "→";
  guideNextButton.setAttribute("aria-label", nextGuideLabel);
  guideNextButton.title = nextGuideLabel;
  guideLayer.classList.remove("is-hidden");
  document.body.classList.add("guide-open");
  setGuideBackgroundInert(true);
  scrollGuideTargetIntoView(guideTarget);
  syncStopsGuideHighlight();
  const renderedStepIndex = activeGuideStepIndex;
  const positionCurrentGuideStep = () => {
    if (
      guideLayer.classList.contains("is-hidden") ||
      activeGuideStepIndex !== renderedStepIndex
    ) {
      return;
    }
    positionGuideCard(guideTarget, step);
    guideCard.classList.remove("is-repositioning");
    if (!reducedMotionQuery.matches) {
      guideCard.classList.add("is-arriving");
      guideArrivalTimer = window.setTimeout(() => {
        guideCard?.classList.remove("is-arriving");
        guideArrivalTimer = null;
      }, guideCardMotionTimings.enter);
    }
    guidePositionFrame = null;
  };
  const positionDelay = guideStepEntersImmediately ? 0 : guideCardMotionTimings.exit;
  guideStepEntersImmediately = false;
  guidePositionTimer = window.setTimeout(() => {
    guidePositionTimer = null;
    guidePositionFrame = requestAnimationFrame(() => {
      guidePositionFrame = requestAnimationFrame(positionCurrentGuideStep);
    });
  }, reducedMotionQuery.matches ? 0 : positionDelay);
}

function finishGuideClose() {
  guideLayer?.classList.add("is-hidden");
  guideLayer?.classList.remove("is-closing-explore");
  guideCard?.classList.remove("is-repositioning");
  isGuideExploreTransitionRunning = false;
  document.body.classList.remove("guide-open");
  setGuideBackgroundInert(false);
  clearGuideHighlight();
}

function closeGuide({ scrollAfterExploreClose = false } = {}) {
  if (!guideLayer || guideLayer.classList.contains("is-closing-explore")) {
    return;
  }

  closeGuideExitConfirmation({ restoreFocus: false });
  window.cancelAnimationFrame(guidePositionFrame);
  window.clearTimeout(guidePositionTimer);
  window.clearTimeout(guideArrivalTimer);
  window.clearTimeout(guideExploreTransitionTimer);
  guidePositionFrame = null;
  guidePositionTimer = null;
  guideArrivalTimer = null;
  guideExploreTransitionTimer = null;
  isGuideExploreTransitionRunning = false;
  guideStepEntersImmediately = false;
  guideCard?.classList.remove("is-arriving");
  const shouldCloseGuidePlayer = guideOpenedPlayerOverlay && overlayOpen;
  guideOpenedPlayerOverlay = false;
  const hasAnimatedExploreReturn = scrollAfterExploreClose && shouldCloseGuidePlayer &&
    playerOverlay?.classList.contains("is-map-panel") &&
    window.matchMedia("(min-width: 1024px)").matches && !reducedMotionQuery.matches;
  if (hasAnimatedExploreReturn) {
    isGuideExploreTransitionRunning = true;
    guideCard?.classList.add("is-repositioning");
    guideLayer.classList.add("is-closing-explore");
    closePlayerOverlay({ returnToGuideHome: true });
    return;
  }

  finishGuideClose();
  if (shouldCloseGuidePlayer) {
    closePlayerOverlay({ returnToGuideHome: scrollAfterExploreClose });
    if (scrollAfterExploreClose) {
      return;
    }
  }
  scrollPageToTop();
}

function startGuide() {
  const firstStop = tappe[0];

  if (firstStop && activeStopNumber !== firstStop.numero) {
    focusStop(firstStop, {
      skipFly: true,
      autoplay: false,
      openOverlay: false,
      replaceUrl: true,
    });
  }

  activeGuideStepIndex = 0;
  renderGuideStep();
  guideNextButton?.focus({ preventScroll: true });
}

function bindHelpControls() {
  if (stopsPanel && miniPlayer) {
    const guideResizeObserver = new ResizeObserver(syncStopsGuideHighlight);
    [stopsPanel, miniPlayer, mapLiveCaption].filter(Boolean).forEach((element) => {
      guideResizeObserver.observe(element);
    });
    if (mapLiveCaption) {
      new MutationObserver(syncStopsGuideHighlight).observe(mapLiveCaption, {
        attributes: true,
        attributeFilter: ["class", "hidden"],
      });
    }
    window.addEventListener("scroll", syncStopsGuideHighlight, { passive: true });
  }
  helpButton?.addEventListener("click", startGuide);
  guideSkipButton?.addEventListener("click", closeGuide);
  guideLayer?.addEventListener("click", (event) => {
    if (event.target === guideLayer) {
      openGuideExitConfirmation();
    }
  });
  guideExitConfirmCancel?.addEventListener("click", () => {
    closeGuideExitConfirmation();
  });
  guideExitConfirmAccept?.addEventListener("click", () => {
    closeGuideExitConfirmation({ restoreFocus: false });
    closeGuide();
  });
  guidePrevButton?.addEventListener("click", () => {
    if (isGuideExploreTransitionRunning) {
      return;
    }
    if (activeGuideStepIndex <= 0) {
      return;
    }

    const steps = getGuideSteps();
    if (!steps[activeGuideStepIndex - 1]?.opensFullPlayer && guideOpenedPlayerOverlay && overlayOpen) {
      closePlayerOverlay();
      guideOpenedPlayerOverlay = false;
    }
    activeGuideStepIndex -= 1;
    renderGuideStep();
  });
  guideNextButton?.addEventListener("click", () => {
    const steps = getGuideSteps();
    const currentStep = steps[activeGuideStepIndex];
    if (isGuideExploreTransitionRunning) {
      return;
    }
    if (activeGuideStepIndex >= steps.length - 1) {
      if (currentStep?.guideTransitionAction === "close") {
        closeGuide({ scrollAfterExploreClose: true });
      } else if (currentStep?.guideTransitionAction === "closePlayer") {
        // Finish the mobile tour through the same X action used by visitors.
        playerCloseButton?.click();
        closeGuide();
      } else {
        closeGuide();
        scrollPageToTop();
      }
      return;
    }

    if (currentStep?.guideTransitionAction === "expand") {
      const guideExploreOrigin = mapStageFrame?.getBoundingClientRect();
      isGuideExploreTransitionRunning = true;
      guideCard?.classList.add("is-repositioning");
      setMapFullscreen(true, { guideExploreOrigin });
      guideExploreTransitionTimer = window.setTimeout(() => {
        guideExploreTransitionTimer = null;
        isGuideExploreTransitionRunning = false;
        guideStepEntersImmediately = true;
        activeGuideStepIndex += 1;
        renderGuideStepAfterExploreLayout();
      }, guideExploreTransitionTimings.map);
      return;
    }

    activeGuideStepIndex += 1;
    renderGuideStep();
  });
  window.addEventListener("resize", () => {
    if (!guideLayer || guideLayer.classList.contains("is-hidden")) {
      return;
    }
    renderGuideStep();
  });

  const preventGuideScroll = (event) => {
    if (!guideLayer || guideLayer.classList.contains("is-hidden")) {
      return;
    }
    event.preventDefault();
  };

  window.addEventListener("wheel", preventGuideScroll, { passive: false });
  window.addEventListener("touchmove", preventGuideScroll, { passive: false });
  window.addEventListener("keydown", (event) => {
    if (!guideLayer || guideLayer.classList.contains("is-hidden")) {
      return;
    }

    if (event.key === "Escape" && isGuideExitConfirmationOpen()) {
      event.preventDefault();
      closeGuideExitConfirmation();
      return;
    }

    if (event.key === "Tab") {
      const focusScope = isGuideExitConfirmationOpen() ? guideExitConfirm : guideLayer;
      const focusable = getVisibleFocusableElements(focusScope);
      if (focusable.length) {
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      }
    }

    const scrollKeys = [" ", "PageDown", "PageUp", "ArrowDown", "ArrowUp", "Home", "End"];
    if (scrollKeys.includes(event.key) && !event.target.closest("button")) {
      event.preventDefault();
    }
  });
}

function renderPlayerLanguageSelector(tappa = null) {
  if (!playerLanguageSelector || !playerLanguageChips) {
    return;
  }

  const targetStop = tappa || tappe.find((item) => item.numero === activeStopNumber) || tappe[0];
  const strings = getUiStrings(currentLanguage);
  const audioOptions = targetStop ? getAudioOptions(targetStop) : [];
  const availableLanguages = audioOptions.filter((option) => option.audioDisponibile);
  const shouldShowSelector = false;

  playerLanguageSelector.hidden = !shouldShowSelector;
  playerLanguageSelector.classList.remove("is-open");
  playerLanguageCurrent?.setAttribute("aria-expanded", "false");
  playerLanguageChips.classList.add("is-menu-hidden");

  if (!shouldShowSelector) {
    playerLanguageChips.innerHTML = "";
    if (playerLanguageLabel) {
      playerLanguageLabel.hidden = true;
    }
    return;
  }

  const selectedCode = selectedLanguageByStop.get(targetStop.numero) || availableLanguages[0]?.codice;
  const selectedOption = availableLanguages.find((option) => option.codice === selectedCode) || availableLanguages[0];
  if (playerLanguageCurrentLabel) {
    playerLanguageCurrentLabel.textContent = getLanguageDisplayName(
      selectedOption?.codice || currentLanguage,
      selectedOption?.codice || currentLanguage,
    );
  }
  if (playerLanguageCurrent) {
    playerLanguageCurrent.setAttribute(
      "aria-label",
      strings.currentLanguage(getLanguageDisplayName(
        selectedOption?.codice || currentLanguage,
        selectedOption?.codice || currentLanguage,
      )),
    );
  }

  playerLanguageChips.innerHTML = "";
  availableLanguages.forEach((option) => {
    const languageCode = option.codice;
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "language-chip tp-chip player-language-option";
    chip.setAttribute("role", "option");
    chip.setAttribute("aria-selected", String(languageCode === selectedOption?.codice));
    chip.textContent = `${languageCode} · ${getLanguageDisplayName(languageCode, languageCode)}`;
    chip.addEventListener("click", () => {
      closePlayerLanguageMenu();
      setCurrentLanguage(languageCode);
      replayAnimationClass(chip, "is-pulsing", 460);
    });
    playerLanguageChips.appendChild(chip);
  });

  if (playerLanguageLabel) {
    playerLanguageLabel.hidden = true;
  }
}

function closePlayerLanguageMenu() {
  playerLanguageSelector?.classList.remove("is-open");
  playerOverlay?.classList.remove("is-language-menu-open");
  playerLanguageChips?.classList.add("is-menu-hidden");
  playerLanguageCurrent?.setAttribute("aria-expanded", "false");
}

function syncPlayerLanguageMenuSurface() {
  if (!playerLanguageChips || !playerLanguageSelector || !playerOverlay) {
    return;
  }

  const isMobile = window.matchMedia("(max-width: 859px)").matches;
  const destination = isMobile ? playerOverlay : playerLanguageSelector;
  if (playerLanguageChips.parentElement !== destination) {
    destination.appendChild(playerLanguageChips);
  }
}

function togglePlayerLanguageMenu() {
  if (!playerLanguageSelector || playerLanguageSelector.hidden) {
    return;
  }

  syncPlayerLanguageMenuSurface();
  const isOpen = playerLanguageSelector.classList.toggle("is-open");
  playerOverlay?.classList.toggle("is-language-menu-open", isOpen);
  playerLanguageChips.classList.toggle("is-menu-hidden", !isOpen);
  playerLanguageCurrent?.setAttribute("aria-expanded", String(isOpen));
  if (isOpen) {
    playerLanguageChips.querySelector("[aria-selected=\"true\"]")?.focus();
  }
}

function renderDetailCopy(tappa) {
  const selectedOption = getSelectedAudioOption(tappa);
  const detailCopy = getDetailCopy(tappa, selectedOption);
  detailCopyTitle.setAttribute("aria-label", detailCopy.title);
  detailCopyTitle.title = detailCopy.title;
  detailDescription.textContent = detailCopy.text;
  renderMobilePlayerTranscript();
  syncMobilePlayerTranscript();
  detailCopyBox.open = false;
  syncDetailCopyPanel();
}

function renderAudioContent(tappa) {
  audioSessionToken += 1;
  audioPlayRequestToken += 1;
  pendingAudioSeek = null;
  isSeekingFromOverlay = false;
  isSeekingFromMiniPlayer = false;
  audioWrapper.innerHTML = "";
  setAudioFeedbackByKey("");
  const selectedOption = getSelectedAudioOption(tappa);
  const strings = getUiStrings(currentLanguage);
  currentSelectedOption = selectedOption;
  loadMapTranscript(tappa, selectedOption);
  audioHasEnded = false;
  updateStopNavigationPreviews(tappa);
  window.requestAnimationFrame(syncMobileTranscriptSheetLayout);

  if (!selectedOption || !selectedOption.audioDisponibile) {
    stopMascotLipSync();
    currentAudio = null;
    updateMiniPlayerPlayback();
    return;
  }

  const audio = document.createElement("audio");
  audio.controls = false;
  // Buffer the selected narration up front so a stop change can start immediately.
  audio.preload = "auto";
  audio.src = selectedOption.fileAudio;
  audio.dataset.mouthCues = getMouthCuePath(selectedOption.fileAudio);
  audio.dataset.audioSession = String(audioSessionToken);
  loadMascotCues(audio.dataset.mouthCues);
  audio.loop = false;
  audio.defaultPlaybackRate = currentPlaybackRate;
  audio.playbackRate = currentPlaybackRate;
  audio.volume = 1;
  audio.muted = false;
  audio.setAttribute(
    "aria-label",
    `${strings.audioAvailable} ${tappa.numero} ${getLanguageDisplayName(
      selectedOption.codice
    ).toLowerCase()}`
  );
  bindAudioLifecycle(audio);
  audioWrapper.appendChild(audio);
  currentAudio = audio;
  updateMediaSession(tappa, selectedOption);
  updateMiniPlayerPlayback();
}

function focusStopByOffset(offset, options = {}) {
  if (isTransitionAudioActive) {
    return;
  }

  if (activeStopNumber === null) {
    return;
  }

  const currentIndex = tappe.findIndex((tappa) => tappa.numero === activeStopNumber);
  if (currentIndex === -1) {
    return;
  }

  const audio = getActiveAudio();
  if (options.manual === true && audio) {
    manuallyNavigatedFromAudio = audio;
  }

  const nextIndex = currentIndex + offset;
  if (nextIndex < 0 || nextIndex >= tappe.length) {
    return;
  }

  focusStop(tappe[nextIndex], {
    autoplay: true,
    openOverlay: overlayOpen,
    scrollRouteIntoView: options.scrollRouteIntoView === true,
  });
}

function handlePreviousAction(options = {}) {
  const now = Date.now();
  const audio = audioWrapper.querySelector("audio");

  if (
    lastPrevInteractionAt &&
    now - lastPrevInteractionAt <= PREVIOUS_TRACK_DOUBLE_TAP_WINDOW_MS
  ) {
    lastPrevInteractionAt = 0;
    focusStopByOffset(-1, { manual: true, scrollRouteIntoView: options.scrollRouteIntoView === true });
    return;
  }

  lastPrevInteractionAt = now;

  if (audio) {
    audio.currentTime = 0;
    updateMiniPlayerPlayback();
  }
}

function formatPlaybackRate(rate) {
  const locale = currentLanguage.toLowerCase();
  const value = new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(rate);
  return `x${value}`;
}

function updatePlaybackRateControl() {
  const label = formatPlaybackRate(currentPlaybackRate);
  const accessibleLabel = `${getUiStrings(currentLanguage).playerSpeed}: ${label}`;
  if (playerSpeedButton && playerSpeedLabel) {
    playerSpeedLabel.textContent = label;
    playerSpeedButton.dataset.rate = String(currentPlaybackRate);
    playerSpeedButton.classList.toggle("is-active", currentPlaybackRate !== PLAYBACK_RATES[0]);
    playerSpeedButton.setAttribute("aria-label", accessibleLabel);
    playerSpeedButton.title = accessibleLabel;
  }

  if (miniPlayerSpeedButton && miniPlayerSpeedLabel) {
    miniPlayerSpeedLabel.textContent = label;
    miniPlayerSpeedButton.dataset.rate = String(currentPlaybackRate);
    miniPlayerSpeedButton.classList.toggle("is-active", currentPlaybackRate !== PLAYBACK_RATES[0]);
    miniPlayerSpeedButton.setAttribute("aria-label", accessibleLabel);
    miniPlayerSpeedButton.title = accessibleLabel;
  }
}

function cyclePlaybackRate() {
  if (isTransitionAudioActive) {
    return;
  }

  const currentIndex = PLAYBACK_RATES.indexOf(currentPlaybackRate);
  setPlaybackRate(PLAYBACK_RATES[(currentIndex + 1) % PLAYBACK_RATES.length]);
}

function setPlaybackRate(rate) {
  if (isTransitionAudioActive || !PLAYBACK_RATES.includes(rate)) {
    return;
  }

  currentPlaybackRate = rate;
  const audio = getActiveAudio();
  if (audio) {
    audio.defaultPlaybackRate = currentPlaybackRate;
    audio.playbackRate = currentPlaybackRate;
  }
  updatePlaybackRateControl();
}

function playCurrentRenderedAudio() {
  const audio = getActiveAudio();
  if (!audio) {
    return;
  }

  const requestToken = ++audioPlayRequestToken;
  const playPromise = audio.play();
  if (playPromise && typeof playPromise.catch === "function") {
    playPromise.catch((error) => {
      if (!isLiveAudio(audio) || requestToken !== audioPlayRequestToken) {
        return;
      }

      if (error?.name === "AbortError") {
        return;
      }

      setAudioFeedbackByKey(navigator.onLine ? "audioLoadError" : "offlineStatus");
      updateMiniPlayerPlayback();
    });
  }
}

function updateActiveListItem(stopNumber) {
  buttonsByStop.forEach((button, numero) => {
    button.classList.toggle("is-active", numero === stopNumber);
    button.setAttribute("aria-pressed", numero === stopNumber ? "true" : "false");
    button.setAttribute("aria-current", numero === stopNumber ? "true" : "false");
  });

  const selectedStop = tappe.find((tappa) => tappa.numero === stopNumber);
  if (stopSelectionStatus && selectedStop) {
    stopSelectionStatus.textContent = `Tappa ${selectedStop.numero}: ${getStopTitle(selectedStop)} selezionata.`;
  }
}

function setPlayerBackgroundInert(isInert) {
  [appShell, miniPlayer].filter(Boolean).forEach((element) => {
    if ("inert" in element) {
      element.inert = isInert;
      return;
    }

    if (isInert) {
      element.setAttribute("aria-hidden", "true");
    } else {
      element.removeAttribute("aria-hidden");
    }
    element.classList.toggle("is-player-background-inert", isInert);
  });
}

function getPlayerFocusableElements() {
  if (!playerSheet) {
    return [];
  }

  return Array.from(
    playerSheet.querySelectorAll(
      'button:not([disabled]), input:not([disabled]), summary, [href], [tabindex]:not([tabindex="-1"])',
    ),
  ).filter((element) => !element.hidden && element.offsetParent !== null);
}

function handlePlayerKeydown(event) {
  if (event.key === "Escape") {
    if (playerLanguageSelector?.classList.contains("is-open")) {
      closePlayerLanguageMenu();
      playerLanguageCurrent?.focus();
      return;
    }

    if (overlayOpen) {
      event.preventDefault();
      closePlayerOverlay();
    }
    return;
  }

  if (
    !overlayOpen ||
    event.key !== "Tab" ||
    playerOverlay?.classList.contains("is-map-panel") ||
    isMobileMapPlayerMode()
  ) {
    return;
  }

  const focusable = getPlayerFocusableElements();
  if (!focusable.length) {
    event.preventDefault();
    playerSheet?.focus();
    return;
  }

  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
}

function openPlayerOverlay(trigger = document.activeElement, options = {}) {
  const isDesktop = window.matchMedia("(min-width: 1024px)").matches;
  if (isDesktop && !isMapFullscreenActive()) {
    if (activeStopNumber === null && tappe[0]) {
      focusStop(tappe[0], { skipFly: true, autoplay: false, openOverlay: false });
    }
    setMapFullscreen(true);
    return;
  }

  if (!options.keepGuideOpen) {
    closeGuide();
  }
  const opensInMobileMapMode = isMobileMapViewport();
  if (opensInMobileMapMode) {
    setMobileMapPlayerMode(true);
  }
  const opensAsMapPanel =
    isMapFullscreenActive() && window.matchMedia("(min-width: 1024px)").matches;

  // Desktop Explore and the mobile map-player view keep the expanded map visible.
  if (isMapFullscreenActive() && !opensAsMapPanel && !opensInMobileMapMode) {
    setMapFullscreen(false);
  }
  window.clearTimeout(playerOpenTransitionTimer);
  window.clearTimeout(playerCloseTransitionTimer);
  playerCloseTransitionTimer = null;
  playerOverlay.classList.remove("is-opening-from-mini");
  if (options.animateFromMini === true && !reducedMotionQuery.matches) {
    playerOverlay.classList.add("is-opening-from-mini");
    playerOpenTransitionTimer = window.setTimeout(() => {
      playerOverlay.classList.remove("is-opening-from-mini");
    }, 440);
  }
  lastPlayerTrigger = trigger instanceof HTMLElement ? trigger : null;
  overlayOpen = true;
  playerOverlay.classList.toggle("is-map-panel", opensAsMapPanel);
  document.body.classList.toggle("is-map-player-panel", opensAsMapPanel);
  playerSheet?.setAttribute("aria-modal", String(!opensAsMapPanel && !opensInMobileMapMode));
  playerOverlay.classList.remove("is-closing");
  playerOverlay.classList.remove("is-hidden");
  playerOverlay.setAttribute("aria-hidden", "false");
  // Explore mode is a non-modal layout: map and mini-player remain interactive.
  setPlayerBackgroundInert(!opensAsMapPanel && !opensInMobileMapMode);
  updatePlayerMapButtonPresentation();
  document.body.classList.add("player-open");
  // Explore changes the caption's available width; repaginate even when audio is paused.
  window.requestAnimationFrame(syncMapLiveCaption);
  syncMascotTapSemantics();
  if (opensAsMapPanel) {
    window.setTimeout(() => map.invalidateSize(), 80);
  }
  document.addEventListener("keydown", handlePlayerKeydown);
  schedulePlayerTitleOverflow();
  window.setTimeout(() => {
    if (!overlayOpen) {
      return;
    }

    // Do not steal focus from a control the user reached during the opening
    // transition. This is especially important for keyboard activation of
    // Play/Pausa immediately after opening the full player.
    if (playerSheet?.contains(document.activeElement)) {
      return;
    }

    const focusTarget = playerCloseButton || playerSheet;
    focusTarget?.focus({ preventScroll: true });
    if (document.activeElement !== focusTarget) {
      playerSheet?.focus({ preventScroll: true });
    }
    schedulePlayerTitleOverflow();
  }, 80);
  syncMiniPlayerReservedSpace();
}

function syncPlayerViewportMode() {
  if (!overlayOpen || !playerOverlay || !mapStageFrame) {
    return;
  }

  const isDesktop = window.matchMedia("(min-width: 1024px)").matches;
  const isExplorePanel = playerOverlay.classList.contains("is-map-panel");
  const isMobileMapMode = isMobileMapPlayerMode();
  if (isDesktop && isMobileMapMode) {
    playerOverlay.classList.remove("is-mobile-map-player");
    document.body.classList.remove("is-mobile-map-player-mode");
    playerOverlay.classList.add("is-map-panel");
    document.body.classList.add("is-map-player-panel", "is-map-fullscreen");
    playerSheet?.setAttribute("aria-modal", "false");
    setPlayerBackgroundInert(false);
    updatePlayerMapButtonPresentation();
    syncMascotTapSemantics();
    window.setTimeout(() => map.invalidateSize(), 80);
    return;
  }
  if (isDesktop && !isExplorePanel) {
    mapStageFrame.classList.add("is-expanded");
    document.body.classList.add("is-map-fullscreen", "is-map-player-panel");
    playerOverlay.classList.add("is-map-panel");
    playerSheet?.setAttribute("aria-modal", "false");
    setPlayerBackgroundInert(false);
    updateMapFullscreenButton();
    updateMapExploreStop();
    syncMascotTapSemantics();
    window.setTimeout(() => map.invalidateSize(), 80);
  } else if (!isDesktop && isExplorePanel) {
    playerOverlay.classList.remove("is-map-panel");
    document.body.classList.remove("is-map-player-panel");
    setMobileMapPlayerMode(true);
    updateMapFullscreenButton();
    syncMascotTapSemantics();
    window.setTimeout(() => map.invalidateSize(), 80);
  }
}

function clearPlayerSharedTransitionNames() {
  [miniPlayerArtwork, miniPlayerTitle, detailArtworkImage, detailTitle].forEach((element) => {
    if (element) {
      element.style.viewTransitionName = "";
    }
  });
}

function openPlayerOverlayFromMini(trigger) {
  if (overlayOpen) {
    return;
  }

  // On narrow screens the shared artwork/title snapshots overlap during the
  // transition, making the track appear twice. Use the single-sheet entrance.
  if (isMobileMapViewport() || reducedMotionQuery.matches || typeof document.startViewTransition !== "function") {
    openPlayerOverlay(trigger, { animateFromMini: !reducedMotionQuery.matches });
    return;
  }

  clearPlayerSharedTransitionNames();
  miniPlayerArtwork.style.viewTransitionName = "tp-player-artwork";
  miniPlayerTitle.style.viewTransitionName = "tp-player-title";

  try {
    const transition = document.startViewTransition(() => {
      miniPlayerArtwork.style.viewTransitionName = "";
      miniPlayerTitle.style.viewTransitionName = "";
      detailArtworkImage.style.viewTransitionName = "tp-player-artwork";
      detailTitle.style.viewTransitionName = "tp-player-title";
      openPlayerOverlay(trigger);
    });

    transition.finished.then(
      clearPlayerSharedTransitionNames,
      clearPlayerSharedTransitionNames,
    );
  } catch (error) {
    clearPlayerSharedTransitionNames();
    openPlayerOverlay(trigger, { animateFromMini: true });
  }
}

function closePlayerOverlay({ returnToGuideHome = false, returnToMap = false } = {}) {
  if (!overlayOpen) {
    return;
  }
  closePlayerContextGuide({ restoreFocus: false });
  overlayOpen = false;
  window.clearTimeout(playerOpenTransitionTimer);
  window.clearTimeout(playerCloseTransitionTimer);
  playerOverlay.classList.remove("is-opening-from-mini");
  const wasMapPanel = playerOverlay.classList.contains("is-map-panel");
  const shouldAnimateDesktopExploreClose =
    wasMapPanel &&
    window.matchMedia("(min-width: 1024px)").matches &&
    !reducedMotionQuery.matches;
  const wasMobileMapMode = isMobileMapPlayerMode();
  clearPlayerSharedTransitionNames();
  closePlayerLanguageMenu();
  playerOverlay.setAttribute("aria-hidden", "true");
  document.removeEventListener("keydown", handlePlayerKeydown);

  if (shouldAnimateDesktopExploreClose && closeDesktopExploreWithTransition({ returnToGuideHome })) {
    return;
  }

  playerOverlay.classList.add("is-closing");

  const finishClose = () => {
    playerOverlay.classList.add("is-hidden");
    playerOverlay.classList.remove("is-closing");
    playerOverlay.classList.remove("is-map-panel");
    playerOverlay.classList.remove("is-mobile-map-player");
    document.body.classList.remove("is-map-player-panel");
    document.body.classList.remove("is-mobile-map-player-mode");
    playerSheet?.setAttribute("aria-modal", "true");
    syncMascotTapSemantics();
    setPlayerBackgroundInert(false);
    document.body.classList.remove("player-open");
    syncMapLiveCaption();
    if (wasMobileMapMode) {
      setMapFullscreen(false);
      restoreStandardMapBounds();
    }
    if (wasMapPanel) {
      setMapFullscreen(false);
      if (returnToGuideHome) {
        window.scrollTo({ top: 0, behavior: "auto" });
        map.invalidateSize();
        focusMapReturnTarget();
      } else {
        window.setTimeout(() => {
          map.invalidateSize();
          mapStageFrame?.scrollIntoView({
            behavior: reducedMotionQuery.matches ? "auto" : "smooth",
            block: "start",
          });
          focusMapReturnTarget();
        }, 80);
      }
    } else if (returnToMap) {
      mapStageFrame?.scrollIntoView({
        behavior: reducedMotionQuery.matches ? "auto" : "smooth",
        block: "start",
      });
      focusMapReturnTarget();
    } else {
      lastPlayerTrigger?.focus({ preventScroll: true });
    }
    syncMiniPlayerReservedSpace();
    playerCloseTransitionTimer = null;
  };

  if (reducedMotionQuery.matches) {
    finishClose();
    return;
  }

  playerCloseTransitionTimer = window.setTimeout(finishClose, 340);
}

function updateMiniPlayer(tappa, selectedOption) {
  setTransitionAudioMode(false);
  playerTranscriptDock.hidden = false;
  miniPlayer.classList.remove("is-hidden");
  const stopTitle = getStopTitle(tappa);
  miniPlayerTitleTrack.textContent = stopTitle;
  miniPlayerTitle.title = stopTitle;
  miniPlayerTitle.setAttribute("aria-label", stopTitle);
  updateMiniPlayerTitleOverflow();
  miniPlayerSubtitle.textContent = "";
  const artworkSrc = STOP_ARTWORKS[tappa.numero] || WHITE_ARTWORK;
  miniPlayerArtwork.src = artworkSrc;
  miniPlayerArtwork.alt = `Artwork tappa ${tappa.numero}`;
  detailArtworkImage.src = artworkSrc;
  detailArtworkImage.alt = `Immagine tappa ${tappa.numero}`;

  if (detailMascotImage) {
    detailMascotImage.src = MASCOT_FRAME_PATHS[currentMascotFrame] || MASCOT_REST_FRAME;
    detailMascotImage.alt = `Mascotte animata di Brunelleschi per tappa ${tappa.numero}`;
  }

  updateMiniPlayerPlayback();
  requestAnimationFrame(syncMiniPlayerReservedSpace);
}

function updateMiniPlayerTitleOverflow() {
  if (!miniPlayerTitle || !miniPlayerTitleTrack) return;
  if (isTransitionAudioActive) {
    miniPlayerTitle.classList.remove("has-overflow");
    miniPlayerTitle.style.removeProperty("--mini-title-distance");
    miniPlayerTitle.style.removeProperty("--mini-title-duration");
    return;
  }
  const overflow = Math.ceil(miniPlayerTitleTrack.getBoundingClientRect().width - miniPlayerTitle.getBoundingClientRect().width);
  const isOverflowing = miniPlayerTitle.clientWidth > 0 && overflow > 2;
  miniPlayerTitle.classList.toggle("has-overflow", isOverflowing);
  if (isOverflowing) {
    miniPlayerTitle.style.setProperty("--mini-title-distance", `${overflow}px`);
    miniPlayerTitle.style.setProperty("--mini-title-duration", `${Math.max(12, 6 + overflow / 11)}s`);
  } else {
    miniPlayerTitle.style.removeProperty("--mini-title-distance");
    miniPlayerTitle.style.removeProperty("--mini-title-duration");
  }
}

if (miniPlayerTitle && miniPlayerTitleTrack && "ResizeObserver" in window) {
  const miniPlayerTitleResizeObserver = new ResizeObserver(updateMiniPlayerTitleOverflow);
  miniPlayerTitleResizeObserver.observe(miniPlayerTitle);
  miniPlayerTitleResizeObserver.observe(miniPlayerTitleTrack);
}

function toggleMiniPlayerPlayback() {
  const audio = getActiveAudio();
  if (isTransitionAudioActive && audio) {
    if (audio.paused) {
      playCurrentRenderedAudio();
    } else {
      audio.pause();
    }
    return;
  }

  if (!audio) {
    if (activeStopNumber !== null) {
      if (window.matchMedia("(min-width: 1024px)").matches) {
        setMapFullscreen(true);
        return;
      }

      openPlayerOverlay(miniPlayerToggle);
    }
    return;
  }

  if (audio.paused) {
    playCurrentRenderedAudio();
    return;
  }

  // Invalidate a play request that may still be resolving before pausing the
  // live element. This prevents a late `playing` event from resurrecting the
  // track after an explicit user pause.
  audioPlayRequestToken += 1;
  audio.pause();
}

function bindPlayerControls() {
  if (detailCopyBox) {
    detailCopyBox.addEventListener("toggle", syncDetailCopyPanel);
  }

  detailCopyPanel?.addEventListener("scroll", syncTranscriptScrollIndicator, { passive: true });
  window.addEventListener("resize", syncTranscriptScrollIndicator);
  syncMascotTapSemantics();
  mascotTapQuery.addEventListener("change", syncMascotTapSemantics);

  const triggerMascotTapReaction = (shell, event) => {
    if (!supportsMascotDirectInteraction(shell)) {
      return;
    }

    event?.stopPropagation();
    if (shell.classList.contains("mascot-motion-shell--hero")) {
      mascotMotionController?.heroTapReaction();
    } else if (shell.classList.contains("map-explore-mascot-motion")) {
      mascotMotionController?.mapTapReaction();
    } else {
      mascotMotionController?.tapReaction();
    }
  };

  getMascotMotionShells().forEach((shell) => {
    shell.addEventListener("click", (event) => {
      triggerMascotTapReaction(shell, event);
    });
    shell.addEventListener("keydown", (event) => {
      if (!supportsMascotDirectInteraction(shell) || (event.key !== "Enter" && event.key !== " ")) {
        return;
      }

      event.preventDefault();
      triggerMascotTapReaction(shell, event);
    });
  });

  if (artworkFlipToggle) {
    artworkFlipToggle.addEventListener("click", (event) => {
      event.stopPropagation();
      setDetailArtworkMode(detailArtworkMode === "mascot" ? "photo" : "mascot");
    });
  }

  if (miniPlayerExpand) {
    miniPlayerExpand.addEventListener("click", (event) => {
      consumeControlEvent(event);
      if (isMobileMapViewport()) {
        openPlayerOverlayFromMini(miniPlayerExpand);
        return;
      }

      setMapFullscreen(true);
    });
  }
  miniPlayer?.addEventListener("click", (event) => {
    const target = event.target;
    if (
      !(target instanceof Element) ||
      target.closest("button, input, a, select, textarea, label, [role='button']")
    ) {
      return;
    }

    if (window.matchMedia("(min-width: 1024px)").matches) {
      setMapFullscreen(true);
      return;
    }

    openPlayerOverlayFromMini(miniPlayer);
  });
  miniPlayerOpen?.addEventListener("click", (event) => {
    event.stopPropagation();
    if (window.matchMedia("(min-width: 1024px)").matches) {
      setMapFullscreen(true);
      return;
    }

    openPlayerOverlayFromMini(miniPlayerOpen);
  });
  miniPlayerOpen?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }

    event.preventDefault();
    if (window.matchMedia("(min-width: 1024px)").matches) {
      setMapFullscreen(true);
      return;
    }

    openPlayerOverlayFromMini(miniPlayerOpen);
  });
  miniPlayerToggle.addEventListener("click", (event) => {
    consumeControlEvent(event);
    toggleMiniPlayerPlayback();
  });
  miniPlayerPreviousTrack?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    handlePreviousAction({ scrollRouteIntoView: isMobileMapViewport() });
  });
  miniPlayerNextTrack?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    focusStopByOffset(1, { manual: true, scrollRouteIntoView: isMobileMapViewport() });
  });
  miniPlayerPrev.addEventListener("click", (event) => {
    consumeControlEvent(event);
    reactToTransport(document.querySelector(".mini-player-transport-group"), "prev");
    if (isCurrentStopWithoutAudio()) {
      focusStopByOffset(-1, { manual: true });
      return;
    }
    seekCurrentAudio(-10);
  });
  miniPlayerNext.addEventListener("click", (event) => {
    consumeControlEvent(event);
    reactToTransport(document.querySelector(".mini-player-transport-group"), "next");
    if (isCurrentStopWithoutAudio()) {
      focusStopByOffset(1, { manual: true });
      return;
    }
    seekCurrentAudio(10);
  });
  miniPlayerSpeedButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    cyclePlaybackRate();
  });
  playerPrevButton.addEventListener("click", (event) => {
    consumeControlEvent(event);
    reactToTransport(document.querySelector(".player-transport-group"), "prev");
    if (isCurrentStopWithoutAudio()) {
      focusStopByOffset(-1, { manual: true });
      return;
    }
    seekCurrentAudio(-10);
  });
  playerPreviousTrack?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    handlePreviousAction();
  });
  playerPlayButton.addEventListener("click", (event) => {
    consumeControlEvent(event);
    toggleMiniPlayerPlayback();
  });
  playerNextButton.addEventListener("click", (event) => {
    consumeControlEvent(event);
    reactToTransport(document.querySelector(".player-transport-group"), "next");
    if (isCurrentStopWithoutAudio()) {
      focusStopByOffset(1, { manual: true });
      return;
    }
    seekCurrentAudio(10);
  });
  playerNextTrack?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    focusStopByOffset(1, { manual: true });
  });
  playerSpeedButton.addEventListener("click", (event) => {
    consumeControlEvent(event);
    cyclePlaybackRate();
  });
  playerBackdrop.addEventListener("click", (event) => {
    consumeControlEvent(event);
    closePlayerOverlay();
  });
  playerCloseButton.addEventListener("click", (event) => {
    consumeControlEvent(event);
    closePlayerOverlay();
  });
  playerMapButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    if (!isMobileMapViewport()) {
      return;
    }

    setMobileMapPlayerMode(!isMobileMapPlayerMode());
  });
  playerMapHelpButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    openPlayerContextGuide("map", playerMapHelpButton);
  });
  playerListenHelpButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    openPlayerContextGuide("listen", playerListenHelpButton);
  });
  playerContextGuideVeil?.addEventListener("click", openPlayerContextGuideExitConfirmation);
  playerContextGuideExitConfirmContinue?.addEventListener("click", () => {
    closePlayerContextGuideExitConfirmation();
  });
  playerContextGuideExitConfirmStop?.addEventListener("click", () => {
    closePlayerContextGuide();
  });
  playerContextGuideClose?.addEventListener("click", () => closePlayerContextGuide());
  playerContextGuidePrev?.addEventListener("click", () => {
    contextGuideStepIndex = Math.max(0, contextGuideStepIndex - 1);
    renderPlayerContextGuideStep();
  });
  playerContextGuideNext?.addEventListener("click", () => {
    const stepCount = getPlayerContextGuideSteps(contextGuideMode).length;
    if (contextGuideStepIndex >= stepCount - 1) {
      closePlayerContextGuide();
      return;
    }
    contextGuideStepIndex += 1;
    renderPlayerContextGuideStep();
  });
  document.addEventListener("keydown", handlePlayerContextGuideKeydown, true);
  playerLanguageCurrent?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    togglePlayerLanguageMenu();
  });
  document.addEventListener("pointerdown", (event) => {
    if (
      playerLanguageSelector?.classList.contains("is-open") &&
      !playerLanguageSelector.contains(event.target) &&
      !playerLanguageChips.contains(event.target)
    ) {
      closePlayerLanguageMenu();
    }
  });
  window.addEventListener("resize", () => {
    syncPlayerViewportMode();
    if (contextGuideMode && !isMobileMapViewport()) closePlayerContextGuide({ restoreFocus: false });
    else positionPlayerContextGuideSpotlight();
    if (playerLanguageSelector?.classList.contains("is-open")) {
      syncPlayerLanguageMenuSurface();
    }
    updateMiniPlayerExpandPresentation();
    schedulePlayerTitleOverflow();
  });
  document.fonts?.ready.then(schedulePlayerTitleOverflow);
  reducedMotionQuery.addEventListener("change", schedulePlayerTitleOverflow);
  playerNextStopButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    focusStopByOffset(1, { manual: true });
  });
  playerPreviousStopButton?.addEventListener("click", (event) => {
    consumeControlEvent(event);
    focusStopByOffset(-1, { manual: true });
  });
  [miniPlayerProgressInput, playerProgressInput].forEach((control) => {
    control.addEventListener("click", stopControlPropagation);
    control.addEventListener("pointerdown", stopControlPropagation);
  });

  const seekFromProgressControl = (control) => {
    const audio = getActiveAudio();
    const duration = getAudioSeekDuration(audio);
    if (!audio || duration === null || isTransitionAudioActive) {
      return null;
    }

    const nextTime = (Number(control.value) / 100) * duration;
    return seekAudioToTime(audio, nextTime) ? audio : null;
  };

  const finishProgressSeek = (control) => {
    if (control === playerProgressInput) {
      if (!isSeekingFromOverlay) return;
      seekFromProgressControl(control);
      isSeekingFromOverlay = false;
    } else {
      if (!isSeekingFromMiniPlayer) return;
      seekFromProgressControl(control);
      isSeekingFromMiniPlayer = false;
    }
    updateMiniPlayerPlayback();
  };

  [playerProgressInput, miniPlayerProgressInput].forEach((control) => {
    ["pointerup", "pointercancel", "blur"].forEach((eventName) => {
      control.addEventListener(eventName, () => finishProgressSeek(control));
    });
  });

  playerProgressInput.addEventListener("input", () => {
    const audio = getActiveAudio();
    if (getAudioSeekDuration(audio) === null) {
      return;
    }
    isSeekingFromOverlay = true;
    seekFromProgressControl(playerProgressInput);
    playerCurrentTime.textContent = formatPlayerTime(audio.currentTime);
    playerProgressInput.style.setProperty("--seek-progress", `${playerProgressInput.value}%`);
  });
  playerProgressInput.addEventListener("change", () => {
    finishProgressSeek(playerProgressInput);
  });
  miniPlayerProgressInput.addEventListener("input", () => {
    const audio = getActiveAudio();
    if (getAudioSeekDuration(audio) === null) {
      return;
    }
    isSeekingFromMiniPlayer = true;
    seekFromProgressControl(miniPlayerProgressInput);
    miniPlayerCurrentTime.textContent = formatPlayerTime(audio.currentTime);
    miniPlayerProgressInput.style.setProperty("--seek-progress", `${miniPlayerProgressInput.value}%`);
  });
  miniPlayerProgressInput.addEventListener("change", () => {
    finishProgressSeek(miniPlayerProgressInput);
  });
}

function updateShareLinks() {
  const strings = getUiStrings(currentLanguage);
  const pageUrl = window.location.href;
  const shareText = `${document.title} - ${strings.intro}`;
  const encodedUrl = encodeURIComponent(pageUrl);
  const encodedText = encodeURIComponent(shareText);
  const encodedTitle = encodeURIComponent(document.title);

  if (shareFacebook) shareFacebook.href = `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`;
  if (shareX) shareX.href = `https://x.com/intent/post?url=${encodedUrl}&text=${encodedText}`;
  if (shareLinkedin) shareLinkedin.href = `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`;
  if (shareWhatsapp) shareWhatsapp.href = `https://wa.me/?text=${encodedText}%20${encodedUrl}`;
}

function bindPlatformLinks() {
  platformsPanel?.addEventListener("click", (event) => {
    const control = event.target.closest(".platform-logo");
    if (!control || !platformsPanel.contains(control)) return;

    const name = control.dataset.platformName || control.textContent.trim();
    const strings = getUiStrings(currentLanguage);
    const rawUrl = control.getAttribute("href") || control.dataset.platformUrl;
    const showError = (message) => {
      event.preventDefault();
      platformLinkStatus.textContent = message;
    };

    if (!rawUrl) {
      showError(strings.platformLinkPending(name));
      return;
    }

    let destination;
    try {
      destination = new URL(rawUrl);
      if (destination.protocol !== "https:") throw new TypeError("Expected an HTTPS URL");
    } catch {
      showError(strings.platformLinkError(name));
      return;
    }

    if (!navigator.onLine) {
      showError(strings.platformLinkOffline(name));
      return;
    }

    platformLinkStatus.textContent = "";
    if (control instanceof HTMLButtonElement) {
      // A destination can be configured later without changing the button's layout.
      const link = document.createElement("a");
      link.href = destination.href;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      link.click();
    }
  });
}

